import random

def get_random_number():
    """Generate a random number between 1 and 100."""
    return random.randint(1, 100)

def get_user_guess():
    """Get a user input as a number between 1 and 100."""
    while True:
        try:
            user_guess = int(input("Guess a number between 1 and 100: "))
            if 1 <= user_guess <= 100:
                return user_guess
            else:
                print("Please enter a number between 1 and 100.")
        except ValueError:
            print("That's not a valid number. Please try again.")

def get_hint(user_guess, random_number):
    """Return a hint ('too high', 'too low', or 'correct') based on user_guess and random_number."""
    if user_guess == random_number:
        return "Correct!"
    elif user_guess > random_number:
        return "Too low, try again!"
    else:
        return "Too high, try again!"

def play_game():
    """Play the game with user input and hints."""
    random_number = get_random_number()
    user_guess = get_user_guess()

    while user_guess != random_number:
        hint = get_hint(user_guess, random_number)
        print(hint)
        user_guess = get_user_guess()

    print(f"Congratulations! You guessed the number {random_number}.")

# Start the game
play_game()
```

This program generates a random number between 1 and 100, gets user input, provides hints based on the user's guess, and continues until the user guesses the correct number.
